package com.company.project.hotel.repository;

import java.util.Collection;
import java.util.List;

/**
 * Room types as the hotel page's room list describes them, implemented in {@code impl/RoomTypeRepositoryImpl}.
 * Which room types can be sold is decided by {@link HotelRepositoryCustom#findRoomRates}; these load the rest for
 * its ids. Nothing here can be generated by Spring Data, so this is a plain interface.
 */
public interface RoomTypeRepository {

	/** These room types, in no particular order. */
	List<RoomTypeDetailView> findDetails(Collection<Long> roomTypeIds);

	/** Their beds, per room type in the order of the bed types. */
	List<RoomBedView> findBeds(Collection<Long> roomTypeIds);

	/** Their room features, per room type by group, then name. */
	List<RoomFeatureView> findFeatures(Collection<Long> roomTypeIds);

	/** Their photos, per room type in their order. */
	List<RoomPhotoView> findPhotos(Collection<Long> roomTypeIds);

}
